'use client';

import { usePreviewToast } from './PreviewToast';

import { useState } from 'react';
import Image from 'next/image';
import { HugeiconsIcon } from '@hugeicons/react';
import { MountainIcon } from '@hugeicons/core-free-icons';
import snow from './assets/abubakarhasan-components-snow.webp.asset';
import alps from './assets/abubakarhasan-components-alps.webp.asset';
import desert from './assets/abubakarhasan-components-desert.webp.asset';

const themes = [
  { name: 'Mount McLoughlin', description: 'A breath of alpine air.', image: snow, alt: 'Snow-covered volcanic summit against a deep blue sky' },
  { name: 'Alps', description: 'The last light on the peaks.', image: alps, alt: 'Jagged alpine peaks glowing orange in the evening light' },
  { name: 'Sahara Desert', description: 'A quieter kind of wilderness.', image: desert, alt: 'Sculptural orange sand dunes at sunset' },
];

export default function LandscapeThemes() {
  const notify = usePreviewToast();
  const [offset, setOffset] = useState(0);
  return <div className="sc-landscape-demo sc-new-demo">
    <div className="sc-landscape-row">
      {[0, 1, 2].map((slot) => { const theme = themes[(slot + offset) % themes.length]; return <article className="sc-landscape-card" key={slot}>
        <Image src={theme.image} alt={theme.alt} fill sizes="(max-width: 640px) 28vw, 200px" />
        <HugeiconsIcon icon={MountainIcon} className="sc-landscape-mark" aria-hidden="true" />
        <div className="sc-landscape-copy"><h3>{theme.name}</h3><p>{theme.description}</p><button type="button" aria-label={`Change ${theme.name} landscape`} onClick={() => { setOffset(value => (value + 1) % themes.length); notify('Landscape theme changed.'); }}>Change</button></div>
      </article>; })}
    </div>
  </div>;
}

'use client';

import { createContext, useCallback, useContext, useEffect, useRef, useState, type ReactNode } from 'react';
import { HugeiconsIcon } from '@hugeicons/react';
import { CheckmarkCircle02Icon } from '@hugeicons/core-free-icons';

const ToastContext = createContext<((message: string) => void) | null>(null);

export function usePreviewToast() {
  const notify = useContext(ToastContext);
  if (!notify) throw new Error('Component previews must be rendered inside PreviewToast.');
  return notify;
}

/** Shared by every preview. Use the hook for actions, or data-preview-toast on simple demo buttons. */
export default function PreviewToast({ children }: { children: ReactNode }) {
  const [toast, setToast] = useState<{ id: number; message: string } | null>(null);
  const sequence = useRef(0);
  const notify = useCallback((message: string) => {
    if (message.trim()) setToast({ id: ++sequence.current, message });
  }, []);

  useEffect(() => {
    if (!toast) return;
    const timer = setTimeout(() => setToast(current => current?.id === toast.id ? null : current), 2800);
    return () => clearTimeout(timer);
  }, [toast]);

  return <ToastContext.Provider value={notify}>
    <div className="sc-toast-boundary" onClick={event => {
      if (!(event.target instanceof Element)) return;
      const trigger = event.target.closest<HTMLElement>('[data-preview-toast]');
      if (trigger && event.currentTarget.contains(trigger)) {
        const message = trigger.dataset.previewToast;
        if (message) notify(message);
      }
    }}>
      {children}
      <div className="sc-toast-layer" role="status" aria-live="polite" aria-atomic="true">
        {toast && <div key={toast.id} className="sc-preview-toast"><HugeiconsIcon icon={CheckmarkCircle02Icon} aria-hidden="true" /><span>{toast.message}</span></div>}
      </div>
    </div>
  </ToastContext.Provider>;
}

export const component = {
  "slug": "landscape-themes",
  "name": "Landscape themes",
  "category": "Personalization · Theme cards",
  "description": "Three atmospheric landscape cards, from snow-covered peaks to the last light on the Alps and warm Sahara dunes. A compact theme-picker concept with an image-first layout.",
  "designStory": "A dark gradient creates a consistent reading surface across very different photographs. The repeated card shape and pale action button keep the collection cohesive while the landscape colors set the mood.",
  "interactionHint": "Select Change on a card to cycle the landscape collection. The change stays within this demo.",
  "stage": "landscapes"
};

import Component from './Preview';
import PreviewToast from './PreviewToast';
import '@fontsource-variable/plus-jakarta-sans';
import './styles.css';

/** Copy this entire folder and import this entry point. */
export default function LandscapeThemes() {
  return <div className="sc-package-landscape-themes"><PreviewToast><Component /></PreviewToast></div>;
}

@reference "tailwindcss";

/* This folder owns its presentation and container sizing. */
@layer components {
  .sc-package-landscape-themes { width:100%; min-width:0; container-type:inline-size; font-family:var(--font-plus-jakarta-sans, "Plus Jakarta Sans Variable"), sans-serif; color:#0F0F0F; }
}


@layer components {
  :where(.sc-package-landscape-themes) .sc-new-demo { @apply relative w-full; font-size:3cqw; letter-spacing:-.04em; }
  :where(.sc-package-landscape-themes) .sc-new-demo button { @apply cursor-pointer; }
  :where(.sc-package-landscape-themes) .sc-new-demo button:focus-visible { @apply outline-2 outline-offset-4 outline-[#6C47FF]; }
  :where(.sc-package-landscape-themes) .sc-landscape-row { @apply grid grid-cols-3; gap:3cqw; }
  :where(.sc-package-landscape-themes) .sc-landscape-card { @apply relative overflow-hidden bg-black text-white; aspect-ratio:.72; border-radius:3cqw; box-shadow:0 2cqw 4cqw #00000012; }
  :where(.sc-package-landscape-themes) .sc-landscape-card > img { @apply object-cover; }
  :where(.sc-package-landscape-themes) .sc-landscape-mark { @apply absolute; top:2.5cqw; left:2.5cqw; width:5cqw; height:4cqw; }
  :where(.sc-package-landscape-themes) .sc-landscape-copy { @apply absolute inset-x-0 bottom-0; padding:9cqw 1.5cqw 1.5cqw; background:linear-gradient(transparent,#000000b3 45%,#000); }
  :where(.sc-package-landscape-themes) .sc-landscape-copy h3 { @apply font-semibold; font-size:4cqw; line-height:1.02; letter-spacing:-.05em; }
  :where(.sc-package-landscape-themes) .sc-landscape-copy p { @apply text-white/55; font-size:1.6cqw; line-height:1.3; margin:1.5cqw 0 2cqw; }
  :where(.sc-package-landscape-themes) .sc-landscape-copy button { @apply w-full bg-[#f1f1f1] font-medium text-black; font-size:1.8cqw; padding:1.5cqw .5cqw; border-radius:2cqw; }
  :where(.sc-package-landscape-themes) .sc-screen-reader { @apply sr-only; }
}
@layer components {
  :where(.sc-package-landscape-themes) .sc-toast-boundary { @apply relative w-full; isolation:isolate; }
  :where(.sc-package-landscape-themes) .sc-toast-layer { @apply pointer-events-none absolute inset-0 z-50 grid place-items-center; padding:4%; }
  :where(.sc-package-landscape-themes) .sc-preview-toast { @apply flex items-center justify-center gap-2 rounded-2xl border border-white/15 bg-[#17131f]/90 px-4 py-3 text-center font-medium text-white shadow-sm backdrop-blur-md; max-width:min(100%,340px); font-size:clamp(10px,2.7cqw,14px); line-height:1.5; overflow-wrap:anywhere; animation:scToastLifecycle 2800ms cubic-bezier(.22,1,.36,1) both; }
  :where(.sc-package-landscape-themes) .sc-preview-toast svg { @apply size-4 shrink-0 text-[#c4b5fd]; }
  @media (prefers-reduced-motion:reduce) { :where(.sc-package-landscape-themes) .sc-preview-toast { animation-name:scToastFade; } }
}
@keyframes scToastLifecycle {
  0% { opacity:0; transform:translateY(6px) scale(.98); }
  12%,72% { opacity:1; transform:translateY(0) scale(1); }
  100% { opacity:0; transform:translateY(-3px) scale(1); }
}
@keyframes scToastFade {
  0% { opacity:0; }
  8%,78% { opacity:1; }
  100% { opacity:0; }
}
